// Canonical pure context model. API copy generated by scripts/sync-gym-profiles.mjs.
import { EQUIPMENT } from './protocol/movements.js'
const ids = new Set(EQUIPMENT.map(e => e.id))
export const cleanEquipment = value => [...new Set((Array.isArray(value) ? value : []).filter(id => ids.has(id)))]
// One gym-wide inventory, editable by an admin through the server. The bundled value is the
// safe first-run/offline fallback; it is never copied into a member's synced gymProfiles state.
export const DEFAULT_2J_EQUIPMENT = ['bodyweight', 'barbell', 'ez_bar', 'dumbbell', 'kettlebell', 'cable', 'weighted', 'selectorized', 'machine', 'plate_loaded', 'smith', 'sled', 'stability_ball', 'roller', 'treadmill', 'bike', 'elliptical', 'stepmill', 'skierg']
let official2jEquipment = [...DEFAULT_2J_EQUIPMENT]
export function setOfficialGymEquipment(value) { official2jEquipment = cleanEquipment(value); return [...official2jEquipment] }
export const officialGymEquipment = () => [...official2jEquipment]
export const OFFICIAL_GYM_PROFILES = [
  { id: '2j', name: '2J Fitness Center', type: 'official', availableEquipment: DEFAULT_2J_EQUIPMENT },
  { id: 'home', name: 'Home gym', type: 'home', availableEquipment: ['bodyweight'] },
  { id: 'hotel', name: 'Hotel', type: 'hotel', availableEquipment: ['bodyweight'] },
]
export function gymProfilesOf(S) {
  const data = S?.gymProfiles || {}
  const official = OFFICIAL_GYM_PROFILES.map(p => ({ ...p, availableEquipment: p.id === '2j' ? [...official2jEquipment] : Array.isArray(data.overrides?.[p.id]) ? cleanEquipment(data.overrides[p.id]) : [...p.availableEquipment] }))
  const seen = new Set(official.map(p => p.id))
  const custom = (Array.isArray(data.custom) ? data.custom : []).slice(0, 12).filter(p => {
    if (!p || typeof p.id !== 'string' || !p.id.startsWith('gym-') || p.id.length > 80 || seen.has(p.id)) return false
    seen.add(p.id); return true
  }).map(p => ({ id: p.id.slice(0, 80), name: String(p.name || 'Custom gym').slice(0, 60), type: p.type === 'other' ? 'other' : 'custom', availableEquipment: cleanEquipment(p.availableEquipment) }))
  return [...official, ...custom]
}
export const activeGymProfile = S => { const profiles = gymProfilesOf(S); return profiles.find(p => p.id === S?.gymProfiles?.activeId) || profiles[0] }
export function selectGymProfile(S, id) {
  if (!gymProfilesOf(S).some(p => p.id === id)) return
  S.gymProfiles = { ...S.gymProfiles, activeId: id }
}
export function saveGymProfile(S, profile) {
  const data = S.gymProfiles || {}
  if (profile.id === '2j') return
  if (['home', 'hotel'].includes(profile.id)) {
    S.gymProfiles = { ...data, overrides: { ...data.overrides, [profile.id]: cleanEquipment(profile.availableEquipment) } }
  } else if (typeof profile.id === 'string' && profile.id.startsWith('gym-') && profile.id.length <= 80) {
    const custom = gymProfilesOf(S).filter(p => p.type === 'other' || p.type === 'custom').filter(p => p.id !== profile.id)
    if (custom.length >= 12) return
    S.gymProfiles = { ...data, custom: [...custom, { id: profile.id.slice(0, 80), name: String(profile.name || 'Custom gym').trim().slice(0, 60), type: profile.type === 'other' ? 'other' : 'custom', availableEquipment: cleanEquipment(profile.availableEquipment) }] }
  }
}
export function gymEquipmentContext(S) {
  const p = activeGymProfile(S)
  return { type: p.type, availableEquipment: p.availableEquipment, scope: 'equipment_categories_not_machine_inventory', authority: 'availability_only; explicit restrictions, safety and training protocol take precedence' }
}
